import{at as e,it as t,t as n,vt as r}from"./chunks/framework.B8HA7oqK.js";var i=JSON.parse(`{"title":"Руководство по разработке","description":"","frontmatter":{},"headers":[],"relativePath":"ru/development/index.md","filePath":"ru/development/index.md","lastUpdated":1765911594000}`),a={name:`ru/development/index.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="руководство-по-разработке" tabindex="-1">Руководство по разработке <a class="header-anchor" href="#руководство-по-разработке" aria-label="Permalink to “Руководство по разработке”">​</a></h1><h2 id="сборка-документации" tabindex="-1">Сборка документации <a class="header-anchor" href="#сборка-документации" aria-label="Permalink to “Сборка документации”">​</a></h2><p>Xray поддерживает различные платформы, и вы можете самостоятельно выполнить кросс-компиляцию на многих из них.</p><p>Перейдите в <a href="./intro/compile.html">документацию по сборке</a>, чтобы узнать больше о процессе сборки.</p><h2 id="принципы-проектирования" tabindex="-1">Принципы проектирования <a class="header-anchor" href="#принципы-проектирования" aria-label="Permalink to “Принципы проектирования”">​</a></h2><p>Ядро Xray предоставляет платформу, на основе которой можно выполнять дальнейшую разработку.</p><p>В этом разделе описываются цели проектирования и архитектура Xray.</p><p>Перейдите в раздел <a href="./intro/design.html">Принципы проектирования</a>, чтобы узнать больше о целях проектирования и архитектуре Xray.</p><h2 id="правила-разработки" tabindex="-1">Правила разработки <a class="header-anchor" href="#правила-разработки" aria-label="Permalink to “Правила разработки”">​</a></h2><p>В этом разделе описываются правила, которым необходимо следовать при получении кода, разработке и отправке запросов на включение изменений (pull request), а также соответствующие стандарты кодирования.</p><p>Перейдите в раздел <a href="./intro/guide.html">Правила разработки</a>, чтобы ознакомиться с правилами, которых следует придерживаться при разработке Xray.</p><h2 id="подробное-описание-протоколов" tabindex="-1">Подробное описание протоколов <a class="header-anchor" href="#подробное-описание-протоколов" aria-label="Permalink to “Подробное описание протоколов”">​</a></h2><p>Xray использует множество различных протоколов, и вы можете получить их подробное описание различными способами.</p><h3 id="протокол-vless" tabindex="-1"><a href="./protocols/vless.html">Протокол VLESS</a> <a class="header-anchor" href="#протокол-vless" aria-label="Permalink to “Протокол VLESS”">​</a></h3><p>VLESS - это легковесный транспортный протокол без сохранения состояния, который может служить мостом между клиентом и сервером Xray.</p><h3 id="протокол-vmess" tabindex="-1"><a href="./protocols/vmess.html">Протокол VMess</a> <a class="header-anchor" href="#протокол-vmess" aria-label="Permalink to “Протокол VMess”">​</a></h3><p>VMess - это зашифрованный транспортный протокол, который может служить мостом между клиентом и сервером Xray.</p><h3 id="протокол-mux-cool" tabindex="-1"><a href="./protocols/muxcool.html">Протокол Mux.Cool</a> <a class="header-anchor" href="#протокол-mux-cool" aria-label="Permalink to “Протокол Mux.Cool”">​</a></h3><p>Протокол Mux.Cool - это транспортный протокол мультиплексирования, который используется для передачи нескольких независимых потоков данных по одному установленному потоку данных.</p><h3 id="протокол-mkcp" tabindex="-1"><a href="./protocols/mkcp.html">Протокол mKCP</a> <a class="header-anchor" href="#протокол-mkcp" aria-label="Permalink to “Протокол mKCP”">​</a></h3><p>mKCP - это потоковый транспортный протокол, основанный на <a href="https://github.com/skywind3000/kcp" target="_blank" rel="noreferrer">протоколе KCP</a>, который может передавать любые потоки данных по порядку.</p>`,21)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};